"""Restore the authors' repository into ./repo without tripping on illegal filenames.

The upstream repo (https://github.com/zubair0831/ensemble-generalization-gap) contains a
figure named ``complexity_mean_|feature_corr|.png``; the ``|`` character is illegal in
Windows paths, so a plain ``git clone`` cannot materialise the working tree.  We therefore
clone with ``--no-checkout`` and restore only text/source/data paths.

Run standalone:  python bootstrap_repo.py
"""
from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

REPO_URL = "https://github.com/zubair0831/ensemble-generalization-gap"
SAFE_SUFFIXES = {".py", ".ipynb", ".md", ".txt", ".csv", ".json", ".yml", ".yaml", ".toml", ".cfg", ".ini"}
HERE = Path(__file__).resolve().parent
REPO_DIR = HERE / "repo"


def _git(args: list[str], check: bool = True) -> subprocess.CompletedProcess:
    return subprocess.run(["git", *args], cwd=str(REPO_DIR) if REPO_DIR.exists() else str(HERE),
                          check=check, text=True, capture_output=True)


def head_files() -> list[str]:
    res = _git(["ls-tree", "-r", "--name-only", "HEAD"], check=False)
    if res.returncode != 0:
        return []
    return [line.strip() for line in res.stdout.splitlines() if line.strip()]


def safe_paths(files: list[str]) -> list[str]:
    out = []
    for f in files:
        if "|" in f or "?" in f or "<" in f or ">" in f or "*" in f or '"' in f:
            continue  # characters illegal on NTFS
        if Path(f).suffix.lower() in SAFE_SUFFIXES:
            out.append(f)
    return out


def ensure_repo(verbose: bool = True) -> dict:
    """Make sure repo/ holds a checkout of the authors' sources.  Returns a status dict."""
    status = {"repo_dir": str(REPO_DIR), "cloned": False, "restored": [], "commit": None, "error": None}

    module = REPO_DIR / "ensemble_experiments.py"
    if module.exists():
        status["commit"] = _git(["rev-parse", "HEAD"], check=False).stdout.strip() or None
        status["restored"] = [module.name]
        if verbose:
            print(f"[bootstrap] repo already restored at {REPO_DIR} (commit {status['commit']})")
        return status

    if not (REPO_DIR / ".git").exists():
        REPO_DIR.parent.mkdir(parents=True, exist_ok=True)
        target = REPO_DIR.name
        res = subprocess.run(["git", "clone", "--no-checkout", REPO_URL, target], cwd=str(HERE),
                             check=False, text=True, capture_output=True)
        if res.returncode != 0:
            status["error"] = f"git clone failed: {res.stderr.strip()[:400]}"
            return status
        status["cloned"] = True

    files = head_files()
    keep = safe_paths(files)
    status["commit"] = _git(["rev-parse", "HEAD"], check=False).stdout.strip() or None

    # Checkout in batches so the command line stays short.
    for i in range(0, len(keep), 20):
        batch = keep[i:i + 20]
        res = _git(["checkout", "HEAD", "--"] + batch, check=False)
        if res.returncode == 0:
            status["restored"].extend(batch)
        else:
            # Retry individually; some paths may still be unmaterialisable.
            for one in batch:
                r1 = _git(["checkout", "HEAD", "--", one], check=False)
                if r1.returncode == 0:
                    status["restored"].append(one)

    if not module.exists():
        status["error"] = "ensemble_experiments.py could not be restored"
    if verbose:
        print(f"[bootstrap] commit={status['commit']} restored={len(status['restored'])} files error={status['error']}")
    return status


if __name__ == "__main__":
    st = ensure_repo()
    print(st)
    sys.exit(0 if (REPO_DIR / "ensemble_experiments.py").exists() else 1)

